package com.smartsociety.platform.notice; import com.smartsociety.platform.auth.User; import jakarta.persistence.*; import java.time.Instant; import java.util.*; @Entity @Table(name="notices",indexes=@Index(name="idx_notice_published",columnList="published,important")) public class Notice {@Id @GeneratedValue(strategy=GenerationType.UUID) UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="author_id")User author;@Column(nullable=false,length=200)String title;@Column(nullable=false,length=10000)String body;boolean important;boolean published;Instant createdAt=Instant.now();Instant publishedAt;public UUID getId(){return id;}public String getTitle(){return title;}public String getBody(){return body;}public boolean isImportant(){return important;}public boolean isPublished(){return published;}public void setAuthor(User x){author=x;}public void setTitle(String x){title=x;}public void setBody(String x){body=x;}public void setImportant(boolean x){important=x;}public void setPublished(boolean x){published=x;publishedAt=x?Instant.now():null;}public Instant getCreatedAt(){return createdAt;} }
